 public static void Validate(){var sc=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var s=UnityEngine.Object.FindAnyObjectByType<DieuPhoiHanhTrinh>();var a=s.GetComponent<ChuanBiHanhLyR41>();
