  var j=new JObject{["scene"]=sc.path,["savedReopened"]=true,["references"]=refs,["missingScripts"]=new JArray(missing),["noRetiredU"]=noU,["r40Migration"]=s.GetComponent<TuTheBaoBenCauV48>().restoreSourceLayoutR40,["Yfix"]=s.GetComponent<PhanChieuMatHo>().resolvedRequestUvR39,["players"]=all.Count(t=>t.GetComponent<DieuKhienDiChuyen>()),["listeners"]=all.Count(t=>t.GetComponent<AudioListener>()),["eventSystems"]=all.Count(t=>t.GetComponent<UnityEngine.EventSystems.EventSystem>()),["serializedHarness"]=all.Any(t=>t.GetComponent<R41SlopeReview>()),["colliders"]=new JArray(a.root.GetComponentsInChildren<Collider>(true).Select(c=>new JObject{["path"]=P(c.transform),["layer"]=c.gameObject.layer,["trigger"]=c.isTrigger,["position"]=V(c.transform.position),["scale"]=V(c.transform.lossyScale)})),["hierarchy"]=new JArray(a.root.GetComponentsInChildren<Transform>(true).Select(t=>new JObject{["path"]=P(t),["components"]=new JArray(t.GetComponents<Component>().Select(c=>c?c.GetType().Name:"MISSING"))}))};
  File.WriteAllText(Out+"/source-reopened.json",j.ToString());if(missing.Length>0||refs.Any(r=>!(bool)r["valid"])||!noU||(bool)j["serializedHarness"])throw new Exception("R41 source validation");
